import json, collections, glob

def aggregate():
    user_totals = collections.defaultdict(lambda: {'amount': 0.0, 'items': []})
    tag_counts = collections.Counter()
    for f in glob.glob('records_*.jsonl'):
        with open(f, 'r') as fr:
            for line in fr:
                data = json.loads(line)
                user = data.get('user', 'unknown')
                user_totals[user]['amount'] += float(data.get('amount', 0))
                user_totals[user]['items'].extend(data.get('items', []))
                for tag in data.get('tags', []):
                    tag_counts[tag] += 1

    top_users = sorted(
        [(u, round(d['amount'], 2), ','.join(d['items'])) for u, d in user_totals.items()],
        key=lambda x: (-x[1], x[0])
    )[:5]
    top_tags = sorted(tag_counts.items(), key=lambda x: (-x[1], x[0]))[:5]

    with open('aggregates.json', 'w') as f:
        json.dump({
            'top_users': [f'{u}: {amt} ({items})' for u, amt, items in top_users]},
            'top_tags': [f'{tag} ({count})' for tag, count in top_tags],
            'total_records': sum(len(list(glob.glob('records_*.jsonl')))))
        }, indent=2)

if __name__ == '__main__':
    aggregate()

